WITH exploded AS (SELECT id, coupon_codes, item.qty, item.promo FROM (SELECT id, coupon_codes, EXPLODE(items) AS item FROM carts) e), scored AS (SELECT id, promo, COUNT(qty) OVER (PARTITION BY promo) AS promo_count_qty, PERCENT_RANK() OVER (PARTITION BY promo ORDER BY qty DESC) AS qty_percent_rank, CUME_DIST() OVER (ORDER BY qty DESC NULLS FIRST) AS qty_cume_dist FROM exploded), enriched AS (SELECT *, COUNT(promo_count_qty) OVER (PARTITION BY promo) AS promo_count_promo_count_qty, CUME_DIST() OVER (ORDER BY promo_count_qty ASC NULLS FIRST) AS promo_count_qty_cume_dist, SUM(qty_cume_dist) OVER (PARTITION BY promo) AS promo_sum_qty_cume_dist, DENSE_RANK() OVER (ORDER BY qty_cume_dist ASC) AS qty_cume_dist_dense_rank FROM scored), base AS (SELECT *, COALESCE(promo, 'N/A') AS promo_filled FROM enriched WHERE promo IS NOT NULL AND qty_cume_dist_dense_rank <> 7), valid AS (SELECT id, promo, promo_count_qty, qty_percent_rank, qty_cume_dist, promo_count_promo_count_qty, promo_count_qty_cume_dist, promo_sum_qty_cume_dist, qty_cume_dist_dense_rank, qty_percent_rank - promo_count_qty AS qty_percent_rank_minus_promo_count_qty, CAST(qty_cume_dist_dense_rank AS STRING) AS qty_cume_dist_dense_rank_str FROM base WHERE promo IS NOT NULL) SELECT promo, qty_percent_rank, qty_cume_dist, promo_count_qty_cume_dist, promo_sum_qty_cume_dist, qty_cume_dist_dense_rank, qty_cume_dist_dense_rank_str, DENSE_RANK() OVER (PARTITION BY promo ORDER BY promo_count_qty DESC) AS promo_count_qty_dense_rank, CUME_DIST() OVER (ORDER BY promo_count_qty_cume_dist DESC NULLS FIRST) AS promo_count_qty_cume_dist_cume_dist, DENSE_RANK() OVER (ORDER BY promo_count_qty ASC NULLS FIRST) AS promo_count_qty_dense_rank_2, MAX(promo_count_promo_count_qty) OVER (PARTITION BY promo) AS promo_max_promo_count_promo_count_qty, ROUND(promo_count_qty / SUM(promo_count_qty) OVER (PARTITION BY promo), 4) AS promo_count_qty_share FROM valid;
